
/* ===== LOGI ZMIAN NA STRONIE (przewijana lista wpisów) =====
   Admin dodaje wpisy (data wpisywana ręcznie, tytuł, treść); gracze przewijają listę.
   Dane: Firebase Realtime Database -> changelog/{id} = {date, title, text, ts, by}
   (stare wpisy changelog/{RRRR-MM-DD} = {text, ts} nadal się wyświetlają).
   Bez Firebase zapis trafia tylko do localStorage tej przeglądarki.
   W treści: linia zaczynająca się od "# " = nagłówek, od "- " = punktor. */
const LOGS={data:{},ref:null,local:false,msg:'',ok:'',edit:null,busy:false};
const LOGS_KEY='dgw_changelog';
const logsIsAdmin=()=>typeof ACC!=='undefined'&&!!ACC.admin;
const logsOpenNow=()=>!!document.getElementById('logsroot');
const logsTodayStr=()=>new Intl.DateTimeFormat('pl-PL',{weekday:'short',day:'numeric',month:'long',year:'numeric'}).format(new Date());
function logsLocalLoad(){try{const o=JSON.parse(localStorage.getItem(LOGS_KEY)||'{}');return o&&typeof o==='object'?o:{}}catch(e){return{}}}
function logsLocalSave(){try{localStorage.setItem(LOGS_KEY,JSON.stringify(LOGS.data))}catch(e){}}
function logsList(){
  return Object.entries(LOGS.data||{}).filter(([k,e])=>e&&typeof e==='object'&&((typeof e.text==='string'&&e.text.trim())||(typeof e.title==='string'&&e.title.trim()))).map(([k,e])=>{
    let date=typeof e.date==='string'?e.date:'';
    if(!date&&/^\d{4}-\d{2}-\d{2}$/.test(k)){const p=k.split('-').map(Number);date=new Intl.DateTimeFormat('pl-PL',{weekday:'short',day:'numeric',month:'long',year:'numeric'}).format(new Date(p[0],p[1]-1,p[2]))}
    return{id:k,date,title:typeof e.title==='string'?e.title:'',text:typeof e.text==='string'?e.text:'',ts:+e.ts||0};
  }).sort((a,b)=>b.ts-a.ts);
}
function logsFmt(text){
  const F=x=>rtFmt(lgEsc(x));
  let h='',inUl=false;
  const close=()=>{if(inUl){h+='</ul>';inUl=false}};
  String(text).split('\n').forEach(l=>{
    const t=l.trim();
    if(!t){close();return}
    if(/^#\s+/.test(t)){close();h+='<h4>'+F(t.replace(/^#\s+/,''))+'</h4>';return}
    if(/^[-•]\s+/.test(t)){if(!inUl){h+='<ul>';inUl=true}h+='<li>'+F(t.replace(/^[-•]\s+/,''))+'</li>';return}
    close();h+='<p>'+F(t)+'</p>';
  });
  close();return h;
}
async function logsOpen(){
  msgClose();
  const d=document.createElement('div');d.id='msgpop';d.setAttribute('role','dialog');d.setAttribute('aria-modal','true');
  d.onclick=e=>{if(e.target===d)msgClose()};document.body.appendChild(d);
  Object.assign(LOGS,{msg:'',ok:'',edit:null,busy:false});
  LOGS.local=!(typeof fbDB!=='undefined'&&fbDB&&typeof onlineEnsureAuth==='function');
  if(LOGS.local){LOGS.data=logsLocalLoad();logsRender();return}
  LOGS.data={};logsRender();
  try{
    await onlineEnsureAuth();
    if(LOGS.ref)LOGS.ref.off();
    LOGS.ref=fbDB.ref('changelog');
    LOGS.ref.on('value',s=>{
      if(!logsOpenNow()){LOGS.ref.off();return}
      LOGS.data=s.val()||{};
      if(LOGS.edit)return;
      logsRender();
    },e=>{LOGS.msg=/permission/i.test(String(e&&(e.code||e.message)))?'Brak uprawnień do odczytu logów. Sprawdź reguły Firebase dla changelog.':'Błąd połączenia: '+(e&&e.message||e);logsRender()});
  }catch(e){LOGS.msg='Nie udało się połączyć z bazą: '+(e&&e.message||e);logsRender()}
}
function logsNew(){if(!logsIsAdmin())return;LOGS.edit={id:null,date:logsTodayStr(),title:'',text:''};LOGS.msg='';LOGS.ok='';logsRender();const e=document.getElementById('logtitle');if(e)e.focus()}
function logsEditId(id){
  if(!logsIsAdmin())return;const p=logsList().find(x=>x.id===id);if(!p)return;
  LOGS.edit={id,date:p.date,title:p.title,text:p.text};LOGS.msg='';LOGS.ok='';logsRender();
}
function logsCancel(){LOGS.edit=null;LOGS.msg='';logsRender()}
function logsEditorHtml(){
  const e=LOGS.edit;
  return `<div class="lged"><label for="logdate">Data (wpisz ręcznie)</label><input id="logdate" maxlength="40" value="${lgEsc(e.date)}" placeholder="np. czw., 8 października" oninput="LOGS.edit.date=this.value"><label for="logtitle">Tytuł</label><input id="logtitle" maxlength="100" value="${lgEsc(e.title)}" placeholder="np. Aktualizacja 1.2" oninput="LOGS.edit.title=this.value"><label for="logta">Treść</label>${rtBar('logta')}<textarea id="logta" maxlength="5000" placeholder="# Nagłówek&#10;- punkt pierwszy&#10;- punkt drugi&#10;&#10;Zwykły akapit…" oninput="LOGS.edit.text=this.value">${lgEsc(e.text)}</textarea><p class="lgnote">Linia zaczynająca się od „# ” to nagłówek, od „- ” to punktor. Zaznacz tekst i użyj B (pogrubienie) lub listy „Rozmiar”.</p><div class="lgrow lgsave"><button class="lgbtn go" onclick="logsSave()"${LOGS.busy?' disabled':''}>${e.id?'Zapisz zmiany':'Opublikuj'}</button><button class="lgbtn" onclick="logsCancel()">Anuluj</button></div></div>`;
}
function logsRender(){
  const d=document.getElementById('msgpop');if(!d)return;
  const adm=logsIsAdmin(),list=logsList();
  const note=LOGS.local?'<p class="lgnote">Tryb lokalny: wpisy zapisują się tylko w tej przeglądarce (brak połączenia z Firebase).</p>':'';
  const posts=list.map(p=>{
    if(LOGS.edit&&LOGS.edit.id===p.id)return logsEditorHtml();
    return `<article class="lgpost"><div><span class="lgtag">Aktualizacja</span>${p.date?`<span class="lgwhen">Zamieszczono ${lgEsc(p.date)}</span>`:''}</div>${p.title?`<h3 class="lgtitle">${lgEsc(p.title)}</h3>`:''}${logsFmt(p.text)}${adm?`<div class="lgrow lgadm"><button class="lgbtn" onclick="logsEditId('${lgEsc(p.id)}')">Edytuj</button></div>`:''}</article>`;
  }).join('');
  d.innerHTML=`<div id="logsroot" class="accbox logbox"><div class="lghead"><h2>Logi zmian</h2><div class="lgrow" style="margin:0">${adm&&!LOGS.edit?'<button class="lgbtn go" onclick="logsNew()">+ Nowy wpis</button>':''}<button class="lgbtn" onclick="msgClose()">Zamknij</button></div></div>${note}
  ${LOGS.msg?`<div class="lgmsg" role="alert">${lgEsc(LOGS.msg)}</div>`:''}${LOGS.ok?`<div class="lgnote">${lgEsc(LOGS.ok)}</div>`:''}
  ${LOGS.edit&&!LOGS.edit.id?logsEditorHtml():''}${posts||(LOGS.edit?'':'<div class="lgempty">Brak wpisów.</div>')}</div>`;
}
async function logsWrite(id,obj){
  if(LOGS.local){if(obj){LOGS.data[id]=Object.assign({ts:Date.now(),by:''},obj)}else delete LOGS.data[id];logsLocalSave();return}
  if(obj)await LOGS.ref.child(id).set(Object.assign({ts:firebase.database.ServerValue.TIMESTAMP,by:(ACC.nick||'').slice(0,30)},obj));
  else await LOGS.ref.child(id).remove();
}
const logsErr=e=>/permission/i.test(String(e&&(e.code||e.message)))?'Brak uprawnień do zapisu. Sprawdź reguły Firebase dla changelog (zapis tylko dla administratorów).':'Błąd zapisu: '+(e&&e.message||e);
async function logsSave(){
  if(!logsIsAdmin()||LOGS.busy||!LOGS.edit)return;
  const e=LOGS.edit,date=(e.date||'').trim().slice(0,40),title=(e.title||'').trim().slice(0,100),text=(e.text||'').trim().slice(0,5000);
  if(!title&&!text){LOGS.msg='Wpisz tytuł lub treść.';LOGS.ok='';logsRender();return}
  LOGS.busy=true;LOGS.msg='';LOGS.ok='';
  try{
    let id=e.id;
    if(!id)id=LOGS.local?'l'+Date.now():LOGS.ref.push().key;
    const old=LOGS.data[id],obj={date,title,text};
    if(e.id&&old&&old.ts)obj.ts=old.ts;   // edycja nie zmienia kolejności
    await logsWrite(id,obj);
    LOGS.edit=null;LOGS.ok='Zapisano.';
  }catch(x){LOGS.msg=logsErr(x)}
  LOGS.busy=false;logsRender();
}
async function logsDel(id){
  if(!logsIsAdmin()||LOGS.busy)return;
  if(!confirm('Usunąć ten wpis?'))return;
  LOGS.busy=true;LOGS.msg='';LOGS.ok='';
  try{await logsWrite(id,null);LOGS.ok='Wpis usunięty.'}
  catch(x){LOGS.msg='Błąd usuwania: '+(x&&x.message||x)}
  LOGS.busy=false;logsRender();
}

const SNL_B64='';
const PCW_B64='';
function pcwOpen(){const h=document.getElementById('hub');if(h)h.style.display='none';document.getElementById('pcw').hidden=false;const f=document.getElementById('pcwFrame');if(!f.dataset.loaded){f.src='gry/pcw/pcw.html';f.dataset.loaded='1'}}
function pcwExit(){document.getElementById('pcw').hidden=true;const h=document.getElementById('hub');if(h)h.style.display=''}
function snlOpen(){const h=document.getElementById('hub');if(h)h.style.display='none';document.getElementById('snl').hidden=false;const f=document.getElementById('snlFrame');if(!f.dataset.loaded){f.src='gry/snl/snl.html';f.dataset.loaded='1'}}
function snlBridge(){return{db:fbDB,auth:onlineEnsureAuth,ts:firebase.database.ServerValue.TIMESTAMP,net:()=>!!(fbDB&&fbAuth),nick:()=>(typeof ACC!=='undefined'&&ACC.nick)||'',col:()=>(typeof ACC!=='undefined'&&/^#[0-9a-f]{6}$/i.test(ACC.col||'')?ACC.col:''),stats:snlStats}}
function snlStats(code,gid,players,r){
  if(!code||!gid||!players||players.length<2||!(r==='w'||r==='l'||r==='d'))return;
  statsRecord('snl_'+String(code).toLowerCase().replace(/[^a-z0-9]/g,'')+'_'+String(gid).toLowerCase().replace(/[^a-z0-9]/g,''),'snl',r,players);
}
function snlExit(){try{const f=document.getElementById('snlFrame');if(f&&f.contentWindow&&f.contentWindow.__snlLeave)f.contentWindow.__snlLeave()}catch(e){}document.getElementById('snl').hidden=true;const h=document.getElementById('hub');if(h)h.style.display=''}
